def log_event(event_type, *details, **metadata):
    print(f"[{event_type.upper()}] Details: {details} | Metadata: {metadata}")

log_event("login", "IP: 192.168.1.1", "User: alex", status="success")

def factorial(n):
    if n <= 1:      # Base case
        return 1
    return n * factorial(n - 1)  # Recursive call

print("5! =", factorial(5))

def apply_twice(func, val):
    return func(func(val))

print("Applied twice:", apply_twice(lambda x: x + 10, 5))

