def sum_to(n):
    if n <= 1:
        return 1
    return n + sum_to(n - 1)
print(sum_to(5))

def calculate_total(base_price, *discounts, tax_rate=0.08):
    current = base_price
    for d in discounts:
        current -= d
    return round(current * (1 + tax_rate), 2)
print(calculate_total(100, 10, 5, tax_rate=0.10))
